import Vue from 'vue'
import Vuex from 'vuex'

Vue.use(Vuex)

export default new Vuex.Store({
  state: {
    currentUid: ''  // 当前登录用户UID
  },
  mutations: {
    SET_UID(state, uid) {
      state.currentUid = uid
    }
  },
  actions: {},
  modules: {}
})
